(()=>{
'use strict';
const U='https://gfggmkeucgqkkyvummpu.supabase.co',K='sb_publishable_ptCVbq9h15prKhT0OO5Zmg_LkE3cb0';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
async function q(path,opts={}){const r=await fetch(U+path,{...opts,headers:{apikey:K,Authorization:`Bearer ${K}`,Accept:'application/json',...(opts.headers||{})}});const t=await r.text();let d=null;try{d=t?JSON.parse(t):null}catch{d=t}if(!r.ok)throw new Error(typeof d==='string'?d:(d?.message||`HTTP ${r.status}`));return d}
function shell(k,t,d,b){return `<div class="page suite-page public-detail-page"><div class="suite-kicker">${esc(k)}</div><h2>${esc(t)}</h2><p class="muted suite-desc">${esc(d)}</p>${b}</div>`}
function activate(id){document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));$(id)?.classList.add('active');document.querySelectorAll('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===id));window.scrollTo({top:0,behavior:'smooth'})}
function wire(){document.querySelectorAll('[data-public-view]').forEach(b=>b.onclick=()=>window.render?.(b.dataset.publicView,b.dataset.arg||''));document.querySelectorAll('[data-problem-id]').forEach(b=>b.onclick=()=>renderDetail(b.dataset.problemId))}
async function renderProblems(){const host=$('problems');if(!host)return;host.innerHTML=shell('MASALAH','Daftar Masalah Publik','Jelajahi masalah yang tercatat, statusnya, wilayah terdampak, serta indikator dampaknya.',`<div class="public-filter"><input id="problem-filter" placeholder="Cari judul masalah atau kategori..."><select id="problem-status"><option value="">Semua status</option><option value="open">Terbuka</option><option value="investigating">Ditelusuri</option><option value="resolved">Selesai</option></select></div><div id="problem-list" class="public-problem-list"><div class="loading">Memuat masalah…</div></div>`);activate('problems');
let all=[];try{all=await q('/rest/v1/problems?select=id,title,category,status,confidence,impact_score,updated_at,region_id&order=updated_at.desc&limit=100')}catch(err){$('problem-list').innerHTML=`<div class="suite-status warn">Data masalah belum dapat dimuat: ${esc(err.message)}</div>`;return}
function paint(){const term=($('problem-filter').value||'').toLowerCase();const st=$('problem-status').value;const rows=all.filter(x=>(!st||x.status===st)&&(!term||`${x.title} ${x.category}`.toLowerCase().includes(term)));$('problem-list').innerHTML=rows.length?rows.map(x=>`<article class="public-problem"><div class="problem-mark">⚠</div><div><h3>${esc(x.title)}</h3><p>${esc(x.category||'Masalah publik')} · diperbarui ${x.updated_at?new Date(x.updated_at).toLocaleDateString('id-ID'):'—'}</p><div class="problem-meta"><span>${esc(x.status||'open')}</span><span>Confidence ${esc(x.confidence??'—')}</span><span>Impact ${esc(x.impact_score??'—')}</span></div></div><button class="btn-outline" data-problem-id="${esc(x.id)}">Lihat detail →</button></article>`).join(''):'<div class="card suite-panel"><b>Tidak ada masalah yang cocok.</b><p class="muted">Coba kata kunci atau status lain.</p></div>';wire()}
$('problem-filter').oninput=paint;$('problem-status').onchange=paint;paint()}
async function renderDetail(id){const host=$('result');if(!host)return;host.innerHTML=shell('DETAIL MASALAH','Memuat…','Memeriksa data publik, wilayah, dan sumber yang tersedia.',`<div class="card suite-panel" id="problem-detail"><div class="loading">Memuat detail masalah…</div></div>`);activate('result');try{const p=(await q(`/rest/v1/problems?select=id,title,category,status,confidence,impact_score,description,summary,created_at,updated_at,region_id&id=eq.${encodeURIComponent(id)}&limit=1`))[0];if(!p)throw new Error('Masalah tidak ditemukan.');let region=null,evidence=[],reports=[];if(p.region_id){try{region=(await q(`/rest/v1/regions?select=id,name,level,admin_code_pum&id=eq.${encodeURIComponent(p.region_id)}&limit=1`))[0]||null}catch{}}try{evidence=await q(`/rest/v1/problem_evidence?select=*&problem_id=eq.${encodeURIComponent(id)}&limit=10`)}catch{}try{reports=await q(`/rest/v1/human_reports?select=id,title,category,verification_status,created_at&problem_id=eq.${encodeURIComponent(id)}&order=created_at.desc&limit=8`)}catch{}
$('problem-detail').innerHTML=`<div class="detail-head"><div><span class="public-kicker">${esc(p.category||'MASALAH PUBLIK')}</span><h1>${esc(p.title)}</h1><p>${esc(p.summary||p.description||'Belum ada ringkasan publik.')}</p></div><span class="detail-status">${esc(p.status||'open')}</span></div><div class="detail-kpis"><div><small>CONFIDENCE</small><b>${esc(p.confidence??'—')}</b></div><div><small>IMPACT</small><b>${esc(p.impact_score??'—')}</b></div><div><small>WILAYAH</small><b>${esc(region?.name||'Belum dipetakan')}</b></div><div><small>DIPERBARUI</small><b>${p.updated_at?new Date(p.updated_at).toLocaleDateString('id-ID'):'—'}</b></div></div><div class="detail-grid"><section><h3>Konteks & status</h3><p>${esc(p.description||'Belum ada uraian konteks yang dipublikasikan.')}</p><h3>Sumber / bukti publik</h3>${evidence.length?evidence.map(x=>`<div class="evidence-row"><b>${esc(x.title||x.source_name||x.evidence_type||'Evidence')}</b><small>${esc(x.url||x.source_uri||x.description||'Sumber tersedia di sistem.')}</small></div>`).join(''):'<div class="empty">Belum ada evidence publik yang ditautkan.</div>'}</section><aside><h3>Wilayah</h3><div class="detail-box"><b>${esc(region?.name||'Belum dipetakan')}</b><small>${esc(region?.level||'')}</small><small>${esc(region?.admin_code_pum||'')}</small></div><h3>Laporan warga terkait</h3>${reports.length?reports.map(x=>`<div class="evidence-row"><b>${esc(x.title)}</b><small>${esc(x.verification_status||'received')} · ${x.created_at?new Date(x.created_at).toLocaleDateString('id-ID'):''}</small></div>`).join(''):'<div class="empty">Belum ada laporan warga yang terhubung.</div>'}</aside></div><div class="detail-actions"><button class="btn-outline" data-public-view="problems">← Kembali ke daftar masalah</button><button class="btn-primary" data-public-view="report" data-arg="${esc(p.title)}">Laporkan informasi terkait</button></div>`;wire()}catch(err){$('problem-detail').innerHTML=`<div class="suite-status warn">${esc(err.message)}</div><button class="btn-outline" data-public-view="problems">Kembali</button>`;wire()}}
const style=document.createElement('style');style.textContent=`.public-detail-page{max-width:1180px;margin:0 auto}.public-filter{display:flex;gap:10px;margin:0 0 14px}.public-filter input,.public-filter select{border:1px solid #dfe7ef;border-radius:10px;padding:11px 13px;background:#fff;font:500 13px Inter;outline:0}.public-filter input{flex:1}.public-problem-list{display:grid;gap:9px}.public-problem{display:grid;grid-template-columns:42px 1fr auto;gap:13px;align-items:center;background:#fff;border:1px solid #e1e9f1;border-radius:13px;padding:13px;box-shadow:0 5px 18px rgba(16,40,74,.035)}.problem-mark{width:38px;height:38px;border-radius:11px;background:#fff3df;display:grid;place-items:center}.public-problem h3{font-size:14px;margin:0 0 4px}.public-problem p{font-size:10px;color:#7e8da0;margin:0}.problem-meta{display:flex;gap:6px;flex-wrap:wrap;margin-top:7px}.problem-meta span,.detail-status{font-size:9px;padding:5px 8px;border-radius:999px;background:#edf5ff;color:#276bb2;font-weight:800}.detail-head{display:flex;justify-content:space-between;gap:20px;background:#fff;border:1px solid #e1e9f1;border-radius:15px;padding:20px}.detail-head h1{font-size:28px;margin:6px 0}.detail-head p{max-width:800px;color:#63758b;line-height:1.6}.detail-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:10px 0}.detail-kpis>div,.detail-box{background:#fff;border:1px solid #e1e9f1;border-radius:12px;padding:13px}.detail-kpis small,.detail-box small{display:block;color:#8795a7;font-size:8px}.detail-kpis b{display:block;font-size:17px;margin-top:4px}.detail-grid{display:grid;grid-template-columns:1.6fr 1fr;gap:10px}.detail-grid section,.detail-grid aside{background:#fff;border:1px solid #e1e9f1;border-radius:13px;padding:16px}.detail-grid h3{font-size:14px;margin:0 0 8px}.detail-grid p{font-size:11px;color:#64758a;line-height:1.6}.evidence-row{padding:9px 0;border-top:1px solid #edf1f5}.evidence-row b{display:block;font-size:10px}.evidence-row small{display:block;color:#8290a2;font-size:9px;margin-top:3px;word-break:break-word}.detail-actions{display:flex;justify-content:space-between;gap:8px;margin-top:10px}@media(max-width:700px){.public-problem{grid-template-columns:36px 1fr}.public-problem .btn-outline{grid-column:2;justify-self:start}.detail-kpis{grid-template-columns:1fr 1fr}.detail-grid{grid-template-columns:1fr}.detail-head{display:block}.detail-status{display:inline-block}.public-filter{flex-direction:column}}`;document.head.appendChild(style);
const old=window.render;window.render=async function(v,x=''){if(v==='problems')return renderProblems();if(v==='problem-detail')return renderDetail(x);return typeof old==='function'?old(v,x):undefined};window.renderProblemDetail=renderDetail;
})();